function printDuration(durationMs) {
  var seconds = Math.floor(durationMs / 1000) % 60;
  var minutes = Math.floor(durationMs / 60000);
  var ms = Math.floor(durationMs % 1000 / 100);
  var hh = minutes > 0 ? "".concat(minutes, ":") : '';
  return "".concat(hh).concat(seconds < 10 ? '0' : '').concat(seconds, ".").concat(ms);
}
